from taf.ul.ettf.msg_capture.expectation_builders.detailed import MessageCallback
from taf.ul.ettf.msg_capture.storage import StoreValueWithUpdate
from taf.ul.ettf.ta_matchers.helpers import FailedMatchingCallback
from taf.ul.ettf.ta_matchers.matchers import StoredValue
from taf.ul.ettf.typed.custom_types import CustomType


class DynamicId(CustomType):
    def __call__(self, object_name):
        instance = self._wrapped_class_instance()

        if instance.is_stored(object_name):
            return instance.get_stored(object_name)
        else:
            dynamic_id = StoredValue()
            self._wrapped_class_instance().store(object_name, dynamic_id, storage_policy=StoreValueWithUpdate)
            self._wrapped_class_instance().append_expectation(MessageCallback(FailedMatchingCallback(dynamic_id.clear)))
            return dynamic_id

    def _wrapped_class_instance(self):
        return self.wrapped_data.args[0]

    def assert_type(self, value):
        pass
